"「일자선택」에서 월 또는 지시일을 선택하세요 (여러 개 선택 가능)":["Select a month or directive date in \"Date Select\" (multiple allowed)","请在「日期选择」中选择月份或指示日（可多选）"],
"「자재구매」처럼 업무별로 어떤 화면을 어디까지 쓰는지 정해 둔 것. 역할을 고치면 그 역할을 쓰는 모든 사람에게 바로 반영됩니다.":["Defines which screens each job (e.g. \"Material Purchasing\") can use and how far. Editing a role applies immediately to everyone with that role.","如「物料采购」一样，按业务规定可使用哪些页面及范围。修改角色后立即反映给使用该角色的所有人。"],
"「전 부서 공통」은 담당부서가 전체인 지시로, 부서별 숫자에는 넣지 않습니다. 정기 보고·행사·일정·전달·부서 내부 지시는 집계에서 뺍니다.":["\"All Depts\" are directives assigned to everyone and are not counted per dept. Regular reports, events, schedules, notices and internal dept directives are excluded from totals.","「全部门共通」是负责部门为全体的指示，不计入各部门数字。定期报告·活动·日程·传达·部门内部指示不计入汇总。"],
