"선택 전에는 빈 업무분장표 양식이, 부서를 고르면 부서 R&R과 부서원 업무분장표가, 이름을 고르면 그 사람의 업무분장표가 나옵니다. 업무분장표는 1.업무분장표 · 2.거래처관리(담당 매입처·매출처, 🔄 자동생성) · 3.변경점관리로 구성되고, 월간 달력은 표 아래에서 펼쳐 봅니다. SMEKR 조직도에서 부서명·이름을 누르면 바로 이동합니다. 수정은 본인·같은 부서 팀장·대표/상무가 할 수 있습니다.":["Before selecting, a blank job assignment form is shown; choosing a dept shows the dept R&R and members' job assignments; choosing a name shows that person's job assignment. It consists of 1. Job Assignment · 2. Partner Management (purchase · sales partners in charge, 🔄 auto-generate) · 3. Change Management, and the monthly calendar opens below the table. Clicking a dept or name in the SMEKR org chart goes there directly. Editing is allowed for the person, the team leader of the same dept and the CEO/Executive Director.","选择前显示空白业务分工表；选择部门后显示部门R&R和部门员工业务分工表；选择姓名后显示该人员的业务分工表。业务分工表由 1.业务分工表 · 2.客户管理（负责的采购方·销售方，🔄 自动生成）· 3.变更点管理组成，月度日历在表格下方展开查看。在SMEKR组织图中点击部门名·姓名可直接跳转。本人·同部门组长·代表/常务可修改。"],
