"으로 등록된 브랜드는 stock_analysis.html 목표대비분석에서 LG사급 실적 계산 시 제외됩니다(재고 미보유·LG마감정산 매입처). 엑셀 업로드 시 이름 기준으로 upsert(같으면 갱신, 없으면 추가)되며 기존 목록은 삭제되지 않습니다.":["— brands registered as such are excluded from LG consigned results in stock_analysis.html target analysis (no stock held · LG closing settlement suppliers). Excel upload upserts by name (update if same, add if new) and does not delete the existing list.","登记的品牌在stock_analysis.html目标对比分析中计算LG代供实绩时排除（不持有库存·LG结账结算采购方）。Excel上传时按名称upsert（相同则更新，没有则添加），不删除原有列表。"],
"으로 분류됩니다. 등록되지 않은 메이커는 자동으로":["is classified. Unregistered makers are automatically","分类。未登记的厂商自动"],
"으로 운영하며 발주 계산에는 사용하지 않습니다.":[", and is not used for order calculation.","运营，不用于订货计算。"],
"은 기한이 있는 지시가 있을 때만 나옵니다(기한이 지났는데 미완료인 건수).":["appears only when there are directives with a deadline (count overdue and incomplete).","仅在有带期限的指示时显示（已过期限且未完成的件数）。"],
"은 분석화면 호환을 위해 유지, 화면에는":["is kept for analysis screen compatibility; on screen","为兼容分析页面而保留，页面上"],
"은 생산지 변경 등으로 같은 부품의 메이커품번이 하나 더 있을 때 입력합니다(예: 스마트전자 대만 RC-80TRJ10K0 ↔ 포산 RCF80TRJ10K0). 출하LOT관리 › 메이커별 품목체계표와":["is entered when the same part has another maker part no. due to a change of production site etc. (e.g. Smart Electronics Taiwan RC-80TRJ10K0 ↔ Foshan RCF80TRJ10K0). With Shipping LOT Management › Item Structure by Maker","在因生产地变更等原因同一零件还有另一个厂商品号时输入（例：Smart电子台湾 RC-80TRJ10K0 ↔ 佛山 RCF80TRJ10K0）。与出货LOT管理 › 按厂商品目体系表"],
"은 인보이스마감 / 당월말 / LG마감 중 선택하며, 목록에는":["is chosen among invoice closing / month-end / LG closing, and the list shows","从发票结账 / 当月末 / LG结账中选择，列表中显示"],
"은 품목에 값이 없을 때 계산에만 임시 적용되며 DB에 저장되지 않습니다. 화면에 [기본값] 표시가 붙습니다.":["applies temporarily only to calculation when the item has no value and is not saved to the DB. A [Default] mark appears on screen.","仅在品目没有值时临时用于计算，不保存到DB。页面上会显示[默认值]标记。"],
"은(는) 거래처 정보·메이커관리에 없는 이름입니다. 거래처로 신규 등록하시겠습니까?":["is not in partner info · Maker Management. Register as a new partner?","不在客户信息·厂商管理中。要登记为新客户吗？"],
"은(는) 거래처 정보에 없는 업체입니다.":["is not a company in partner info.","不在客户信息中。"],
"은(는) 거래처 정보에 없는 이름입니다.":["is not in partner info.","不在客户信息中。"],
"은(는) 메이커관리에 없는 메이커입니다.":["is not a maker in Maker Management.","不在厂商管理中。"],
