"은(는) 이미 다른 항목(비활성 포함)에 등록되어 있어 사용할 수 없습니다":["is already registered to another item (including inactive) and cannot be used","已登记在其他项目（含停用）中，无法使用"],
"은(는) 추가 항목을 최대 20개까지만 등록할 수 있습니다. 설정 탭에서 안 쓰는 항목을 정리한 후 다시 추가해주세요.":["— up to 20 extra items can be registered. Clean up unused items in the Settings tab and add again.","最多只能登记20个追加项目。请在设置标签中整理不用的项目后再添加。"],
"을 선택(Ctrl+A) 후 복사(Ctrl+C)해서 아래에 붙여넣으세요(Ctrl+V). 헤더를 빼거나 일부 컬럼만 복사하면 인식이 안 되니, 필요없는 컬럼도 골라내지 말고 통째로 복사해주세요.":["— select all (Ctrl+A), copy (Ctrl+C) and paste below (Ctrl+V). Removing the header or copying only some columns will not be recognized, so copy everything without removing unneeded columns.","— 全选(Ctrl+A)后复制(Ctrl+C)，再粘贴到下方(Ctrl+V)。去掉标题或只复制部分列将无法识别，请不要挑选列，整体复制。"],
