"인상·인하는 기존 단가를 지우지 않습니다. 기존 줄은 「적용일 하루 전」까지로 닫히고 새 줄이 생겨 이력이 남습니다. 같은 적용일로 다시 등록하면 그 줄을 고칩니다. 변동구분을 비워두면 판매가 기준으로 인상/인하/매입변경을 자동으로 정합니다.":["Increases · decreases do not delete existing prices. The existing row is closed \"one day before the effective date\" and a new row is created, keeping history. Registering again with the same effective date edits that row. If change type is blank, increase/decrease/purchase change is determined automatically from the selling price.","上调·下调不会删除原有单价。原有行截止到「适用日前一天」并生成新行，保留履历。以相同适用日再次登记则修改该行。变动类别留空时按销售价自动判定上调/下调/采购变更。"],
