"판매 영향":["Sales Impact","销售影响"],
"판매 영향 = 최근 3개월 해당 매출처 판매수량 ÷ 3(월평균) × 판매가 차이 · 매입 영향 = 같은 수량 × 매입가 차이 · 순영향 = 판매 영향 − 매입 영향. (기본) 단가는 특가가 없는 매출처 전체 수량 기준.":["Sales impact = last 3 months' sales qty to that customer ÷ 3 (monthly avg) × selling price difference · Purchase impact = same qty × purchase price difference · Net impact = sales impact − purchase impact. (Default) price uses the total qty of customers without special prices.","销售影响 = 最近3个月该销售方销售数量 ÷ 3（月平均）× 销售价差异 · 采购影响 = 相同数量 × 采购价差异 · 净影响 = 销售影响 − 采购影响。（默认）单价以无特价的全部销售方数量为准。"],
