"합니다. 기초재고(재고원장)는 실사수량으로 들어가며, 재확인 수량이 실사와 다르게 확정되면 그 차이가 「실사조정」으로 재고원장에 자동 반영됩니다. 이카운트 재고조정은 별도로 해주세요.":[". Opening stock (stock ledger) is entered as the physical count; if the recheck qty is confirmed differently from the count, the difference is automatically posted to the stock ledger as a \"Stocktake Adjustment\". Please do the iCount stock adjustment separately.","。期初库存（库存台账）以实盘数量录入，若再确认数量与实盘不同并被确定，该差异会作为「盘点调整」自动反映到库存台账。iCount库存调整请另行处理。"],
